mapper.select:
SELECT mb.branch_id, mb.name AS branch_name, mb.branch_type, mb.address, mb.latitude, mb.longitude, mb.phone, bs.schedule_id, bs.service_date, bs.start_at, bs.end_at, fs.service_id, fs.service_code, fs.service_name, fs.category AS service_category, bss.preparation_note FROM mobile_branches mb INNER JOIN branch_schedules bs ON bs.branch_id = mb.branch_id LEFT JOIN branch_services bss ON bss.branch_id = mb.branch_id LEFT JOIN financial_service_types fs ON fs.service_id = bss.service_id AND fs.is_active = TRUE WHERE mb.is_active = TRUE AND bs.status = 'SCHEDULED' AND bs.end_at > #{now, jdbcType=TIMESTAMP}
AND EXISTS ( SELECT 1 FROM branch_services filter_bss INNER JOIN financial_service_types filter_fs ON filter_fs.service_id = filter_bss.service_id WHERE filter_bss.branch_id = mb.branch_id AND filter_fs.is_active = TRUE AND filter_fs.service_code = #{serviceCode, jdbcType=VARCHAR} )
ORDER BY bs.start_at ASC, mb.branch_id ASC, fs.service_code ASC
